import { useId } from "react";

function EmailField() {
  const id = useId(); // e.g. ":r3:"
  return (
    <>
      <label htmlFor={id}>Email</label>
      <input id={id} type="email" />
    </>
  );
}

const errorSummaryRef = useRef(null);

function handleSubmit(e) {
  e.preventDefault();
  const errs = validate();
  setErrors(errs);
  // Move focus to error summary so SR reads it
  setTimeout(() => errorSummaryRef.current?.focus(), 50);
}

<div ref={errorSummaryRef} tabIndex={-1} role="alert">
  <h2>Please fix 2 errors:</h2>
  <ul>
    <li><a href="#name-id">Name is required</a></li>
  </ul>
</div>

function handleSubmit(e) {
  e.preventDefault();
  const errs = validate();
  setErrors(errs);
  if (Object.keys(errs).length > 0) {
    // 1. Focus error summary for screen readers
    errorSummaryRef.current?.focus();
    // 2. Scroll first invalid field into view for sighted users
    const firstErrRef =
      errs.name  ? nameRef  :
      errs.email ? emailRef :
      errs.role  ? roleRef  : agreeRef;
    firstErrRef.current?.scrollIntoView({
      behavior: "smooth",
      block: "center",
    });
  }
}

// Toggle switch
<button role="switch" aria-checked={isOn}
  onClick={() => setIsOn(v => !v)}>
  <span className="sr-only">{isOn ? "On" : "Off"}</span>
</button>

// Star rating
<div role="radiogroup" aria-label="Rate experience">
  <button role="radio" aria-checked={rating === 3}
    aria-label="3 stars"
    onKeyDown={e => {
      if (e.key === "ArrowRight") setRating(r => r + 1);
      if (e.key === "ArrowLeft")  setRating(r => r - 1);
    }}>★</button>
</div>

// ✓ Three signals: icon, text, and color
<span style={{ color: "#c47d00" }}>
  <span aria-hidden="true">⚠ </span>{" "}
